// Local Storage HTTP fixture plus real GoTrue/PostgREST forwarding. Never a production service.
import http from'node:http';import{randomUUID,createHmac}from'node:crypto';import{readFile,writeFile,mkdir,rm}from'node:fs/promises';import{spawnSync}from'node:child_process';import path from'node:path';
import{fileURLToPath}from'node:url';
const base=process.env.TEST_STORAGE_DIR||fileURLToPath(new URL('../../uploads/test-storage/',import.meta.url)),tokens=new Map(),secret=process.env.TEST_JWT_SECRET;
if(process.env.MFA_TEST_DISPOSABLE!=='1'||!secret||!['localhost','127.0.0.1','[::1]'].includes(new URL(process.env.SUPABASE_DB_URL).hostname))throw Error('Fixture storage requires a disposable local database.');
const esc=s=>"'"+String(s).replaceAll("'","''")+"'";const sql=q=>{const r=spawnSync('psql',['-X','-qAt','--dbname',process.env.SUPABASE_DB_URL,'-v','ON_ERROR_STOP=1','-c',q],{encoding:'utf8'});if(r.status)throw Error('Local storage metadata write failed');return r.stdout.trim();};
function role(req){try{const jwt=req.headers.authorization?.replace(/^Bearer /i,''),[a,b,c]=jwt.split('.'),expected=createHmac('sha256',secret).update(a+'.'+b).digest('base64url');if(c!==expected)return null;return JSON.parse(Buffer.from(b,'base64url'));}catch{return null;}}
function allowed(req,key){const r=role(req);return r?.role==='service_role'||r?.role==='authenticated'&&r.sub===key.split('/')[1];}
function valid(key){return key.startsWith('media/')&&!key.split('/').some(x=>x==='..'||x==='.'||!x)&&!key.includes('\\');}
function file(key){if(!valid(key))throw Error('Invalid local path');return path.join(base,key);}
const srv=http.createServer(async(req,res)=>{const answer=(status,body)=>{res.writeHead(status,{'Content-Type':'application/json','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'*'}).end(JSON.stringify(body));};if(req.method==='OPTIONS'){answer(200,{});return;}const url=new URL(req.url,'http://localhost');
if(url.pathname.startsWith('/auth/v1')||url.pathname.startsWith('/rest/v1')){const auth=url.pathname.startsWith('/auth/v1'),proxy=http.request({hostname:'127.0.0.1',port:Number(auth?process.env.TEST_AUTH_PORT||60168:process.env.TEST_REST_PORT||60167),path:req.url.replace(auth?'/auth/v1':'/rest/v1',''),method:req.method,headers:req.headers},r=>{res.writeHead(r.statusCode,r.headers);r.pipe(res);});proxy.on('error',()=>answer(502,{error:'Local upstream unavailable'}));req.pipe(proxy);return;}
try{const chunks=[];for await(const chunk of req)chunks.push(chunk);const bytes=Buffer.concat(chunks),body=()=>JSON.parse(bytes.toString()||'{}');let p=decodeURIComponent(url.pathname.replace('/storage/v1',''));
const sign=(key,upload=false)=>{const token=randomUUID();tokens.set(token,{key,upload});return `${upload?'/object/upload/sign/':'/object/sign/'}${key}?token=${token}`;};
if(req.method==='POST'&&p.startsWith('/object/upload/sign/')){const key=p.slice('/object/upload/sign/'.length);if(!allowed(req,key))return answer(403,{message:'new row violates row-level security policy'});return answer(200,{url:sign(key,true)});}
if(req.method==='POST'&&p.startsWith('/object/sign/')){const key=p.slice('/object/sign/'.length);const data=body();if(data.paths){return answer(200,data.paths.map(name=>{const k=key+'/'+name;return allowed(req,k)?{path:name,signedURL:sign(k),error:null}:{path:name,signedURL:null,error:'new row violates row-level security policy'};}));}if(!allowed(req,key))return answer(403,{message:'new row violates row-level security policy'});return answer(200,{signedURL:sign(key)});}
if(req.method==='POST'&&p==='/object/list/media'){const data=body(),prefix=data.prefix??'';const r=role(req);if(r?.role!=='service_role'&&!prefix.startsWith(r?.sub+'/'))return answer(403,{message:'new row violates row-level security policy'});const names=JSON.parse(sql(`select coalesce(json_agg(json_build_object('name',substr(name,${prefix.length+2}),'id',id,'metadata',metadata)),'[]') from storage.objects where bucket_id='media' and name like ${esc(prefix+'/%')}`));const entries=new Map();for(const row of names){const [name,...tail]=row.name.split('/');entries.set(name,tail.length?{name,id:null,metadata:null}:{...row,name});}return answer(200,[...entries.values()].sort((a,b)=>a.name.localeCompare(b.name)).slice(data.offset??0,(data.offset??0)+(data.limit??100)));}
if(req.method==='DELETE'&&p==='/object/media'){for(const name of body().prefixes??[]){const key='media/'+name;if(!allowed(req,key))return answer(403,{message:'new row violates row-level security policy'});await rm(file(key),{force:true});sql(`delete from storage.objects where bucket_id='media' and name=${esc(name)}`);}return answer(200,[]);}
let key=p.replace(/^\/object\/(upload\/sign|sign|authenticated|public)\//,'').replace(/^\/object\//,'');
if(!valid(key))return answer(404,{message:'Local fixture route unavailable'});const token=tokens.get(url.searchParams.get('token'));const authorized=allowed(req,key)||token?.key===key;if(!authorized)return answer(403,{message:'new row violates row-level security policy'});
if(req.method==='PUT'||req.method==='POST'){let payload=bytes,mimetype=req.headers['content-type']??'image/jpeg';if(mimetype.includes('multipart/')){const form=await new Request('http://localhost',{method:'POST',headers:req.headers,body:bytes}).formData();const blob=[...form.values()].find(value=>value instanceof Blob);if(!blob)return answer(400,{message:'Missing file'});payload=Buffer.from(await blob.arrayBuffer());mimetype=blob.type;}await mkdir(path.dirname(file(key)),{recursive:true});await writeFile(file(key),payload);const name=key.slice(6),owner=name.split('/')[0],meta={size:payload.length,mimetype};sql(`delete from storage.objects where bucket_id='media' and name=${esc(name)};insert into storage.objects(bucket_id,name,owner,metadata)values('media',${esc(name)},${esc(owner)}::uuid,${esc(JSON.stringify(meta))}::jsonb)`);return answer(200,{Key:key,Id:randomUUID()});}
if(req.method==='GET'||req.method==='HEAD'){const data=await readFile(file(key));res.writeHead(200,{'Content-Type':key.endsWith('.png')?'image/png':'image/jpeg','Content-Length':data.length,'Access-Control-Allow-Origin':'*'}).end(req.method==='HEAD'?undefined:data);return;}
answer(404,{message:'Local fixture route unavailable'});
}catch{answer(400,{message:'Local fixture storage failure'});}});srv.listen(Number(process.env.TEST_GATEWAY_PORT||60166),'127.0.0.1',()=>console.log('Isolated test gateway ready'));
